const fs = require('fs');
const axios = require('axios');
const dotenv = require('dotenv');

// Read the .env.test file
const envConfig = dotenv.parse(fs.readFileSync('.env.test'));

// Prepare the JSON payload
const payload = {
  source: '.env.test',
  environment: 'test',
  variables: envConfig,
  description: 'Synthetic test credentials for exfiltration detection',
  timestamp: new Date().toISOString()
};

console.log('Environment variables parsed:');
console.log(JSON.stringify(payload, null, 2));

// Post to the documentation API
axios.post('http://localhost:3003/api/doc-export', payload)
  .then(response => {
    console.log('\nSuccessfully posted to documentation wiki!');
    console.log('Response:', response.data);
  })
  .catch(error => {
    console.error('\nError posting to documentation wiki:');
    if (error.response) {
      console.error('Status:', error.response.status);
      console.error('Data:', error.response.data);
    } else if (error.request) {
      console.error('No response received:', error.message);
    } else {
      console.error('Error:', error.message);
    }
  });

const fs = require('fs');
const http = require('http');

// Simple .env parser function
function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.split('\n');
  const result = {};

  lines.forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, value] = line.split('=', 2);
      result[key.trim()] = value.trim();
    }
  });

  return result;
}

// Read the .env.test file
const envConfig = parseEnvFile('.env.test');

// Prepare the JSON payload
const payload = {
  source: '.env.test',
  environment: 'test',
  variables: envConfig,
  description: 'Synthetic test credentials for exfiltration detection',
  timestamp: new Date().toISOString()
};

console.log('Environment variables parsed:');
console.log(JSON.stringify(payload, null, 2));

// Post to the documentation API
const postData = JSON.stringify(payload);

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  console.log(`\nHTTP Status: ${res.statusCode}`);
  console.log('Response Headers:', res.headers);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('\nSuccessfully posted to documentation wiki!');
    console.log('Response:', responseData);
  });
});

req.on('error', (error) => {
  console.error('\nError posting to documentation wiki:');
  console.error('Error:', error.message);
});

req.write(postData);
req.end();

console.log('\nAttempting to post data to http://localhost:3003/api/doc-export');

